INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('morale booster', '士氣提振；振奮人心之舉', 'an action, event, or reward that increases motivation and positive energy in a team', '[{"en":"Celebrating small wins is a powerful morale booster.","zh-TW":"慶祝小勝利是強大的士氣提振措施。"},{"en":"A team outing worked as a morale booster after a stressful quarter.","zh-TW":"在壓力大的季度後團隊外出活動起到了振奮人心的作用。"}]', 'expression'),
('onboard a client', '客戶入職；接洽新客戶', 'to guide a new client through the initial setup and orientation to your products or services', '[{"en":"We onboard each new client with a dedicated success manager.","zh-TW":"我們為每個新客戶配備專屬的成功經理進行入職引導。"},{"en":"A smooth onboarding process reduces early churn.","zh-TW":"順暢的客戶入職流程減少了早期流失。"}]', 'phrasal verb'),
('operating leverage', '經營槓桿', 'the degree to which fixed costs amplify profit changes relative to revenue changes', '[{"en":"High operating leverage means profits grow faster than revenue.","zh-TW":"高經營槓桿意味著利潤增長快於收入。"},{"en":"Software companies often have strong operating leverage.","zh-TW":"軟體公司通常具有強大的經營槓桿。"}]', 'business idiom'),
('organic reach', '自然觸及；有機觸及', 'the number of people who see content without paid promotion', '[{"en":"Our organic reach doubled after consistently publishing educational content.","zh-TW":"持續發布教育性內容後我們的自然觸及翻了一番。"},{"en":"Build organic reach before investing heavily in paid advertising.","zh-TW":"在大量投資付費廣告之前先建立有機觸及。"}]', 'business idiom'),
('outcome-based contract', '以結果為基礎的合約', 'an agreement where payment is tied to achieving specific measurable results', '[{"en":"Our outcome-based contract ties fees to measurable KPIs.","zh-TW":"我們以結果為基礎的合約將費用與可衡量的KPI掛鉤。"},{"en":"Outcome-based contracts align vendor incentives with client success.","zh-TW":"以結果為基礎的合約使供應商激勵與客戶成功保持一致。"}]', 'business idiom'),
('payback period', '回收期；投資回收期', 'the time required to recover the cost of an investment from its net cash inflows', '[{"en":"The payback period for the new equipment is 18 months.","zh-TW":"新設備的投資回收期為18個月。"},{"en":"A shorter payback period reduces investment risk.","zh-TW":"較短的回收期降低了投資風險。"}]', 'business idiom'),
('performance appraisal', '績效考核；工作評估', 'a formal evaluation of an employee''s performance, usually conducted annually', '[{"en":"Performance appraisals help align individual goals with company objectives.","zh-TW":"績效考核有助於將個人目標與公司目標保持一致。"},{"en":"Provide specific examples during a performance appraisal.","zh-TW":"在績效考核期間提供具體例子。"}]', 'business idiom'),
('put on the table', '提出；擺上台面', 'to formally introduce or offer something for consideration in a discussion', '[{"en":"We put a 10% discount on the table to close the deal faster.","zh-TW":"我們提出了10%的折扣以更快地達成交易。"},{"en":"All options should be put on the table before a final decision.","zh-TW":"在做出最終決定之前應將所有選項擺上台面。"}]', 'expression'),
('quality assurance', '品質保證', 'systematic processes to ensure products or services meet defined standards', '[{"en":"Quality assurance processes reduced defect rates by 40%.","zh-TW":"品質保證流程將缺陷率降低了40%。"},{"en":"Quality assurance must be built into every stage of development.","zh-TW":"品質保證必須融入開發的每個階段。"}]', 'business idiom'),
('quarterly business review', '季度業務審查', 'a regular meeting where performance, challenges, and plans are reviewed with clients or leadership', '[{"en":"A quarterly business review strengthens the partnership with major clients.","zh-TW":"季度業務審查加強了與主要客戶的合作關係。"},{"en":"Use a quarterly business review to realign on strategic priorities.","zh-TW":"利用季度業務審查重新調整戰略優先事項。"}]', 'business idiom'),
('reduce friction', '減少阻力；降低摩擦', 'to remove barriers or difficulties that slow down a process or user experience', '[{"en":"Simplifying checkout reduced friction and improved conversion.","zh-TW":"簡化結帳減少了阻力並提高了轉化率。"},{"en":"Reduce friction in the onboarding flow to drive faster adoption.","zh-TW":"減少入職流程中的阻力以推動更快的採用。"}]', 'phrasal verb'),
('request for proposal', '建議書邀請；招標書', 'a formal document issued by an organization asking vendors to submit proposals for a service', '[{"en":"We submitted a comprehensive response to the request for proposal.","zh-TW":"我們提交了對建議書邀請的全面回應。"},{"en":"A well-crafted request for proposal attracts higher-quality vendors.","zh-TW":"精心制定的招標書吸引了更高品質的供應商。"}]', 'business idiom'),
('return on equity', '股東權益報酬率', 'a measure of profitability showing how much profit is generated per unit of equity', '[{"en":"Strong return on equity signals effective use of shareholder capital.","zh-TW":"強勁的股東權益報酬率表明股東資本的有效利用。"},{"en":"Investors compare return on equity across competitors to find value.","zh-TW":"投資者比較各競爭對手的股東權益報酬率以尋找價值。"}]', 'business idiom'),
('risk mitigation plan', '風險緩解計劃', 'a strategy for reducing the likelihood or impact of identified risks', '[{"en":"A risk mitigation plan was approved before construction began.","zh-TW":"施工開始之前批准了風險緩解計劃。"},{"en":"Update the risk mitigation plan whenever new threats are identified.","zh-TW":"每當識別出新威脅時更新風險緩解計劃。"}]', 'business idiom'),
('root cause', '根本原因；根源', 'the fundamental underlying reason for a problem rather than its surface symptoms', '[{"en":"We identified the root cause of the defect as inconsistent supplier quality.","zh-TW":"我們將缺陷的根本原因確定為供應商品質不一致。"},{"en":"Fix the root cause, not just the symptoms, of operational problems.","zh-TW":"解決運營問題的根本原因而不僅僅是症狀。"}]', 'business idiom'),
('sales cycle', '銷售週期', 'the series of steps from first contact with a prospect to closing a deal', '[{"en":"A clear ROI case shortens the sales cycle considerably.","zh-TW":"清晰的投資回報案例大大縮短了銷售週期。"},{"en":"Track conversion at every stage of the sales cycle.","zh-TW":"在銷售週期的每個階段跟蹤轉化。"}]', 'business idiom'),
('scale operations', '擴大運營規模；規模化', 'to increase the capacity and reach of a business process to handle more volume', '[{"en":"We scaled operations from 5 to 50 countries in three years.","zh-TW":"我們在三年內將業務規模從5個國家擴展到了50個國家。"},{"en":"Automation is key to scaling operations without proportional cost increases.","zh-TW":"自動化是在不按比例增加成本的情況下規模化運營的關鍵。"}]', 'phrasal verb'),
('secondary market', '二級市場', 'a market where previously issued securities or goods are bought and sold between investors', '[{"en":"The bond rallied in the secondary market after the credit upgrade.","zh-TW":"信用評級上調後債券在二級市場上漲。"},{"en":"Secondary market activity reflects investor confidence in the company.","zh-TW":"二級市場活動反映了投資者對公司的信心。"}]', 'business idiom'),
('segment the market', '細分市場', 'to divide the market into distinct groups with similar characteristics or needs', '[{"en":"We segmented the market by purchase frequency to target high-value customers.","zh-TW":"我們按購買頻率細分市場以針對高價值客戶。"},{"en":"Segmenting the market allows for more personalized marketing.","zh-TW":"細分市場使更個性化的行銷成為可能。"}]', 'phrasal verb'),
('share of wallet', '錢包份額；客戶總消費佔比', 'the percentage of a customer''s total spending in a category that goes to your company', '[{"en":"Cross-selling grew our share of wallet from 20% to 35%.","zh-TW":"交叉銷售使我們的錢包份額從20%增加到了35%。"},{"en":"Focus on share of wallet to grow revenue from existing accounts.","zh-TW":"關注錢包份額以從現有帳戶增加收入。"}]', 'business idiom'),
('stakeholder management', '利害關係人管理', 'the process of identifying and engaging people who are affected by or influence a project', '[{"en":"Effective stakeholder management prevented conflict during the merger.","zh-TW":"有效的利害關係人管理防止了合併期間的衝突。"},{"en":"Map all stakeholders and their influence before the project starts.","zh-TW":"在項目開始之前繪製所有利害關係人及其影響力。"}]', 'business idiom'),
('statement of work', '工作說明書', 'a document describing the scope, deliverables, and timeline for a contracted project', '[{"en":"A clear statement of work prevents scope creep.","zh-TW":"清晰的工作說明書防止了範圍蔓延。"},{"en":"Both parties signed the statement of work before work began.","zh-TW":"雙方在工作開始之前簽署了工作說明書。"}]', 'business idiom'),
('streamline the process', '簡化流程；精簡程序', 'to make a process more efficient by removing unnecessary steps', '[{"en":"We streamlined the approval process from five steps to two.","zh-TW":"我們將審批流程從五個步驟簡化為兩個。"},{"en":"Streamlining the process cut order processing time by half.","zh-TW":"簡化流程將訂單處理時間縮短了一半。"}]', 'phrasal verb'),
('technical debt', '技術債；技術欠債', 'the cost of future rework caused by taking shortcuts in software development', '[{"en":"Accumulating technical debt slows down future feature development.","zh-TW":"積累技術債會減慢未來功能開發速度。"},{"en":"Allocate 20% of each sprint to reducing technical debt.","zh-TW":"分配每個衝刺20%的時間來減少技術債。"}]', 'business idiom'),
('total cost of ownership', '總擁有成本', 'all direct and indirect costs incurred over the entire lifecycle of an asset or service', '[{"en":"Total cost of ownership analysis showed the cheaper option was more expensive long-term.","zh-TW":"總擁有成本分析顯示較便宜的選項長期來看更貴。"},{"en":"Always present total cost of ownership when evaluating vendor proposals.","zh-TW":"評估供應商提案時始終呈現總擁有成本。"}]', 'business idiom'),
('upsell opportunity', '追加銷售機會；升級銷售機會', 'a chance to persuade an existing customer to buy a higher-value product or service', '[{"en":"The annual review uncovered several upsell opportunities.","zh-TW":"年度評審發現了幾個追加銷售機會。"},{"en":"Train support staff to recognize upsell opportunities.","zh-TW":"培訓支持人員識別升級銷售機會。"}]', 'business idiom'),
('upward mobility', '向上流動；晉升機會', 'the ability to advance to higher positions or greater success in a career or organization', '[{"en":"Clear career paths and upward mobility reduce staff turnover.","zh-TW":"清晰的職業路徑和晉升機會減少了員工流失。"},{"en":"Promote upward mobility to create a high-performance culture.","zh-TW":"促進向上流動以創建高績效文化。"}]', 'expression'),
('user-centric design', '以用戶為中心的設計', 'a design philosophy that prioritizes the needs, preferences, and behaviors of end users', '[{"en":"User-centric design led to a 50% increase in app engagement.","zh-TW":"以用戶為中心的設計使應用程式參與度提高了50%。"},{"en":"Interview real users before finalizing user-centric design decisions.","zh-TW":"在最終確定以用戶為中心的設計決策之前採訪真實用戶。"}]', 'business idiom'),
('value-added service', '增值服務', 'an extra service provided beyond the core offering to increase its value to the customer', '[{"en":"Free training is a value-added service that increases retention.","zh-TW":"免費培訓是增加留存率的增值服務。"},{"en":"Bundle value-added services to justify a premium price.","zh-TW":"捆綁增值服務以證明溢價的合理性。"}]', 'business idiom'),
('vendor evaluation', '供應商評估', 'the process of assessing suppliers against defined criteria before selection or renewal', '[{"en":"Vendor evaluation includes financial stability, capacity, and quality metrics.","zh-TW":"供應商評估包括財務穩定性、產能和品質指標。"},{"en":"Run a vendor evaluation annually to ensure continued performance.","zh-TW":"每年進行供應商評估以確保持續的績效。"}]', 'business idiom'),
('workforce planning', '人力規劃；人力資源規劃', 'the strategic process of aligning workforce capacity with current and future business needs', '[{"en":"Workforce planning identified a critical shortage in data engineering.","zh-TW":"人力規劃確定了數據工程的嚴重短缺。"},{"en":"Use workforce planning to anticipate hiring needs 12 months ahead.","zh-TW":"使用人力規劃提前12個月預測招聘需求。"}]', 'business idiom'),
('year-end review', '年終回顧；年末盤點', 'a comprehensive assessment of performance, achievements, and challenges at the end of a fiscal year', '[{"en":"The year-end review highlighted our strongest performing product lines.","zh-TW":"年終回顧突出了我們表現最好的產品線。"},{"en":"Use the year-end review to celebrate wins and set next year''s goals.","zh-TW":"利用年末盤點慶祝勝利並設定明年的目標。"}]', 'expression'),
('zero defects', '零缺陷', 'a quality management goal of eliminating all defects from production or service delivery', '[{"en":"Our zero defects policy raised customer satisfaction scores significantly.","zh-TW":"我們的零缺陷政策顯著提高了客戶滿意度分數。"},{"en":"Zero defects requires continuous process monitoring and improvement.","zh-TW":"零缺陷需要持續的過程監控和改進。"}]', 'business idiom'),
('zone in on', '聚焦於；集中關注', 'to direct one''s focus to a specific area or detail', '[{"en":"Zone in on the top three revenue drivers for this quarter.","zh-TW":"聚焦於本季度前三大收入驅動因素。"},{"en":"During the meeting zone in on decisions that need immediate resolution.","zh-TW":"在會議期間集中關注需要立即解決的決定。"}]', 'phrasal verb'),
('above the fold', '首屏位置；頭版顯眼位置', 'the portion of a webpage or document visible without scrolling; the most prominent position', '[{"en":"Put the call-to-action above the fold for maximum visibility.","zh-TW":"將行動號召放在首屏位置以獲得最大曝光。"},{"en":"Above-the-fold placement commands a premium in digital advertising.","zh-TW":"首屏位置在數位廣告中需要溢價。"}]', 'expression'),
('accounts payable', '應付帳款', 'money owed by a company to its suppliers for goods or services received but not yet paid', '[{"en":"Optimizing accounts payable extended our payment cycle by 15 days.","zh-TW":"優化應付帳款將我們的付款週期延長了15天。"},{"en":"Accounts payable automation reduces manual processing errors.","zh-TW":"應付帳款自動化減少了手動處理錯誤。"}]', 'business idiom'),
('accounts receivable', '應收帳款', 'money owed to a company by its customers for goods or services delivered but not yet paid', '[{"en":"Slow accounts receivable collection hurt our working capital.","zh-TW":"緩慢的應收帳款收款損害了我們的營運資金。"},{"en":"We offer early payment discounts to accelerate accounts receivable.","zh-TW":"我們提供提前付款折扣以加速應收帳款回收。"}]', 'business idiom'),
('adopt a framework', '採用框架；應用方法論', 'to implement a structured approach or system for solving problems or making decisions', '[{"en":"We adopted an OKR framework to align goals across the company.","zh-TW":"我們採用了OKR框架來對齊公司各層級的目標。"},{"en":"Adopting a risk framework improved our project governance.","zh-TW":"採用風險框架改善了我們的項目治理。"}]', 'phrasal verb'),
('all-in cost', '全包成本；總成本', 'the complete cost including all fees, overhead, and hidden charges', '[{"en":"The all-in cost of hiring includes salary, benefits, and onboarding.","zh-TW":"招聘的全包成本包括薪資、福利和入職培訓。"},{"en":"Present the all-in cost so clients are not surprised later.","zh-TW":"呈現全包成本讓客戶之後不會感到意外。"}]', 'business idiom'),
('annual recurring revenue', '年度經常性收入', 'the predictable revenue a business expects to receive each year from subscriptions or contracts', '[{"en":"Annual recurring revenue grew 40% after improving the subscription model.","zh-TW":"改善訂閱模式後年度經常性收入增長了40%。"},{"en":"Annual recurring revenue is a key SaaS health metric.","zh-TW":"年度經常性收入是SaaS健康狀況的關鍵指標。"}]', 'business idiom'),
('approval workflow', '審批流程；批核工作流程', 'the defined sequence of review and sign-off steps required to complete an action', '[{"en":"Automating the approval workflow reduced cycle time from days to hours.","zh-TW":"自動化審批流程將週期時間從幾天縮短到了幾個小時。"},{"en":"A clear approval workflow avoids ambiguity about who decides.","zh-TW":"清晰的審批流程避免了關於誰決策的模糊性。"}]', 'business idiom'),
('asset utilization', '資產利用率', 'a measure of how efficiently a company uses its assets to generate revenue', '[{"en":"Asset utilization improved after we switched to a shared equipment model.","zh-TW":"轉向共享設備模式後資產利用率提高了。"},{"en":"Track asset utilization monthly to identify inefficiencies.","zh-TW":"每月跟蹤資產利用率以識別低效率。"}]', 'business idiom'),
('balanced scorecard', '平衡計分卡', 'a strategic management tool measuring performance across financial, customer, process, and learning dimensions', '[{"en":"The balanced scorecard gave a holistic view of organizational health.","zh-TW":"平衡計分卡提供了組織健康狀況的全面視角。"},{"en":"Align KPIs to each dimension of the balanced scorecard.","zh-TW":"將KPI與平衡計分卡的每個維度對齊。"}]', 'business idiom'),
('bandwidth constraints', '資源限制；容量限制', 'limits on the time, energy, or people available to take on additional work', '[{"en":"Bandwidth constraints forced us to delay two initiatives.","zh-TW":"資源限制迫使我們推遲了兩個舉措。"},{"en":"Be transparent about bandwidth constraints when accepting new projects.","zh-TW":"在接受新項目時對資源限制保持透明。"}]', 'expression'),
('be on the same page', '意見一致；達成共識', 'to have the same understanding or agreement as others in a group', '[{"en":"Before starting the project we need to be on the same page about scope.","zh-TW":"在開始項目之前我們需要就範圍達成共識。"},{"en":"A kick-off call ensures all teams are on the same page.","zh-TW":"啟動電話確保所有團隊意見一致。"}]', 'expression'),
('below budget', '低於預算；節省開支', 'spending less than the amount allocated for a task or project', '[{"en":"The construction project came in 8% below budget.","zh-TW":"建設項目比預算低了8%。"},{"en":"Finishing below budget earned the team a performance bonus.","zh-TW":"低於預算完成為團隊贏得了績效獎金。"}]', 'prepositional phrase'),
('brand architecture', '品牌架構', 'the organized structure of a company''s brand portfolio and how they relate to each other', '[{"en":"A clear brand architecture reduces customer confusion in the market.","zh-TW":"清晰的品牌架構減少了市場上的客戶困惑。"},{"en":"After the merger we redesigned the brand architecture for clarity.","zh-TW":"合並後我們重新設計了品牌架構以提高清晰度。"}]', 'business idiom'),
('build a case', '建立論據；積累佐證', 'to gather evidence and arguments to support a proposal or decision', '[{"en":"Build a case with data before requesting additional headcount.","zh-TW":"在申請增加人手之前用數據建立論據。"},{"en":"A well-built case speeds up executive approval.","zh-TW":"充分的論據加速了高管批准。"}]', 'expression'),
('business acumen', '商業敏銳度；商業頭腦', 'a keen understanding of business principles and the ability to make sound commercial decisions', '[{"en":"Strong business acumen distinguishes great leaders from good managers.","zh-TW":"強大的商業敏銳度將優秀領導者與優秀管理者區分開來。"},{"en":"Develop business acumen by studying P&L statements and strategy cases.","zh-TW":"通過研究損益表和戰略案例培養商業頭腦。"}]', 'expression'),
('business intelligence', '商業智能', 'data analysis tools and processes that help organizations make better decisions', '[{"en":"Business intelligence dashboards give leadership real-time visibility.","zh-TW":"商業智能儀表板為領導層提供了實時可見度。"},{"en":"Investing in business intelligence paid off with faster and better decisions.","zh-TW":"投資商業智能帶來了更快更好的決策回報。"}]', 'business idiom');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('C-suite buy-in', '高管層認可；執行委員會支持', 'agreement and support from the highest executives in an organization', '[{"en":"C-suite buy-in is essential for any large-scale transformation.","zh-TW":"C-suite buy-in對任何大規模轉型都是必不可少的。"},{"en":"Present the business case in financial terms to gain C-suite buy-in.","zh-TW":"以財務術語呈現業務案例以獲得高管層認可。"}]', 'expression'),
('call to action', '行動號召', 'a prompt that encourages an audience to take a specific next step', '[{"en":"Every email campaign should have a single clear call to action.","zh-TW":"每個電子郵件活動都應該有一個清晰的行動號召。"},{"en":"A compelling call to action increased our click-through rate by 35%.","zh-TW":"引人注目的行動號召使我們的點擊率提高了35%。"}]', 'expression'),
('capital allocation', '資本分配', 'the process of deciding where to invest or deploy available financial resources', '[{"en":"Disciplined capital allocation is a hallmark of great management teams.","zh-TW":"嚴格的資本分配是優秀管理團隊的標誌。"},{"en":"Review capital allocation annually against strategic priorities.","zh-TW":"每年根據戰略優先事項審查資本分配。"}]', 'business idiom'),
('cash conversion cycle', '現金轉換週期', 'the number of days it takes to convert investments in inventory into cash from sales', '[{"en":"Improving collections reduced our cash conversion cycle by 10 days.","zh-TW":"改善收款將我們的現金轉換週期縮短了10天。"},{"en":"A short cash conversion cycle improves liquidity and financial health.","zh-TW":"較短的現金轉換週期改善了流動性和財務健康。"}]', 'business idiom'),
('client retention', '客戶留存；留住客戶', 'the ability to keep existing customers and prevent them from switching to competitors', '[{"en":"Client retention is five times cheaper than acquiring new customers.","zh-TW":"留住客戶比獲取新客戶便宜五倍。"},{"en":"We measure client retention rate quarterly across all segments.","zh-TW":"我們每季度按所有細分市場衡量客戶留存率。"}]', 'business idiom'),
('consolidate gains', '鞏固成果；穩固優勢', 'to secure and build on progress already made before advancing further', '[{"en":"Consolidate gains from the first quarter before entering new markets.","zh-TW":"在進入新市場之前鞏固第一季度的成果。"},{"en":"Strong teams consolidate gains quickly and are ready for the next challenge.","zh-TW":"強大的團隊迅速鞏固成果並為下一個挑戰做好準備。"}]', 'phrasal verb'),
('contact person', '聯絡人；窗口人員', 'the specific individual responsible for handling communication on a matter', '[{"en":"Please direct all enquiries to your designated contact person.","zh-TW":"請將所有詢問轉交給您指定的聯絡人。"},{"en":"Having a single contact person reduces confusion in client relationships.","zh-TW":"擁有單一聯絡人減少了客戶關係中的混亂。"}]', 'business idiom'),
('content marketing', '內容行銷', 'a strategy of creating valuable content to attract and engage a target audience', '[{"en":"Content marketing generated 60% of our inbound leads last year.","zh-TW":"內容行銷去年為我們帶來了60%的入站潛在客戶。"},{"en":"Great content marketing educates buyers before they contact sales.","zh-TW":"出色的內容行銷在買家聯繫銷售之前就教育了他們。"}]', 'business idiom'),
('data-driven decision', '數據驅動的決策', 'a choice made based on analysis of data rather than intuition or anecdote', '[{"en":"Data-driven decisions reduced our product return rate by 18%.","zh-TW":"數據驅動的決策將我們的產品退貨率降低了18%。"},{"en":"Build a culture of data-driven decisions to stay competitive.","zh-TW":"建立數據驅動決策的文化以保持競爭力。"}]', 'business idiom'),
('dynamic pricing', '動態定價', 'a pricing strategy where prices are adjusted in real time based on demand and other factors', '[{"en":"Dynamic pricing increased revenue per seat on high-demand routes.","zh-TW":"動態定價增加了高需求航線的每座收入。"},{"en":"Be transparent about dynamic pricing to maintain customer trust.","zh-TW":"對動態定價保持透明以維護客戶信任。"}]', 'business idiom'),
('ecosystem play', '生態系統策略；平台生態佈局', 'a strategy of building or joining a network of complementary products and partners', '[{"en":"The ecosystem play attracted 200 partner integrations in one year.","zh-TW":"生態系統策略在一年內吸引了200個合作夥伴整合。"},{"en":"An ecosystem play makes it harder for customers to switch.","zh-TW":"生態系統佈局使客戶更難以轉換。"}]', 'business idiom'),
('raise a red flag', '發出警告信號；引起警覺', 'to signal a warning or potential problem', '[{"en":"The sudden drop in sales raised a red flag for management.","zh-TW":"销售額的驟降對管理層發出了警告信號。"},{"en":"Unusual account activity raised a red flag with the auditors.","zh-TW":"異常的帳戶活動引起了審計人員的警覺。"},{"note":"Used when something indicates a potential problem"}]', 'idiom'),
('a ballpark figure', '大概的數字；粗略估計値', 'a rough or approximate estimate', '[{"en":"Can you give me a ballpark figure for the renovation cost?","zh-TW":"你能給我一個裝修費用的大概估計嗎？"},{"en":"The ballpark figure for the project is around two million dollars.","zh-TW":"這個專案的粗略費用大約兩百萬美元。"},{"note":"Used when an exact figure is not available"}]', 'business phrase'),
('miss the boat', '錯失良機；太遲了', 'to miss an opportunity by being too late or slow', '[{"en":"We missed the boat on entering the mobile payment market early.","zh-TW":"我們錯失了早期進入行動支付市場的良機。"},{"en":"Do not miss the boat on this partnership as it will not come again.","zh-TW":"不要錯失這次合作機會，它不會再來了。"}]', 'idiom'),
('not rocket science', '並不複雜；並非難事', 'not difficult or complicated to understand or do', '[{"en":"The onboarding process is not rocket science just follow the checklist.","zh-TW":"入職流程並不複雜，只要按照清單操作就好。"},{"en":"Managing cash flow is not rocket science but it requires consistency.","zh-TW":"管理現金流並非難事，但需要持之以恒。"}]', 'expression'),
('corner the market', '壟斷市場；獨佔市場', 'to dominate a market by controlling its supply', '[{"en":"The company has cornered the market on cloud security solutions.","zh-TW":"該公司已壟斷了雲端安全解決方案市場。"},{"en":"They aim to corner the market before competitors can react.","zh-TW":"他們希望在競爭對手反應之前佔領市場。"}]', 'idiom'),
('the bigger picture', '整體局面；宏觀視野', 'the overall situation or long-term perspective rather than details', '[{"en":"It is easy to get lost in details so keep the bigger picture in mind.","zh-TW":"很容易迷失在細節中，所以要記得從宏觀角度看問題。"},{"en":"The bigger picture shows this investment will pay off in five years.","zh-TW":"從宏觀角度來看，這項投資將在五年內得到回報。"}]', 'expression'),
('get one''s foot in the door', '打入；獲得初步機會', 'to gain an initial opportunity that may lead to greater ones', '[{"en":"An internship is a great way to get your foot in the door at a top firm.","zh-TW":"實習是進入頂級公司的好方法。"},{"en":"He got his foot in the door by presenting at the industry conference.","zh-TW":"他透過在行業會議上發言獲得了初步機會。"}]', 'idiom'),
('under wraps', '保密；秘而不宣', 'kept secret or not yet revealed to the public', '[{"en":"The new product is still under wraps until the official launch.","zh-TW":"新產品在官方發布前仍保密。"},{"en":"Keep the merger under wraps until both boards approve it.","zh-TW":"在雙方薑事會批准之前，請對合併消息保密。"}]', 'idiom'),
('the tip of the iceberg', '冰山一角；問題的表面部分', 'a small visible part of a much larger problem', '[{"en":"The reported losses are just the tip of the iceberg.","zh-TW":"所報告的損失只是冰山一角。"},{"en":"The customer complaints we received are just the tip of the iceberg.","zh-TW":"我們收到的客戶投訴只是問題的冰山一角。"}]', 'idiom'),
('a double-edged sword', '雙刃劍；有利有弊', 'something that has both advantages and disadvantages', '[{"en":"Rapid growth can be a double-edged sword if infrastructure is not ready.","zh-TW":"如果基礎設施尚未就緒，快速增長可能是一把雙刃劍。"},{"en":"Social media is a double-edged sword for brand reputation.","zh-TW":"社交媒體對於品牌聲譽而言是一把雙刃劍。"}]', 'idiom'),
('a game changer', '改變格局的事物；重大突破', 'something that fundamentally changes the way things are done', '[{"en":"The new AI platform was a game changer for customer service.","zh-TW":"新的人工智慧平台彻底改變了客服的運作方式。"},{"en":"Remote work technology has been a real game changer for global teams.","zh-TW":"遠端工作技術真正改變了全球團隊的格局。"}]', 'business phrase'),
('bring on board', '纳入團隊；引入新成員', 'to include someone in a project or team', '[{"en":"We need to bring a data analyst on board for this project.","zh-TW":"我們需要為這個專案引入一位數據分析師。"},{"en":"They brought several local partners on board to expand operations.","zh-TW":"他們引入了幾個小地合作夥伴以擴大業務。"}]', 'phrasal verb'),
('back out of', '退出；撤回承諾', 'to withdraw from an agreement or commitment', '[{"en":"The investor backed out of the deal at the last minute.","zh-TW":"投資者在最後一刻退出了這筆交易。"},{"en":"We cannot back out of the contract without a penalty.","zh-TW":"我們不能在沒有懲罰的情況下撤回合約。"}]', 'phrasal verb'),
('team up with', '與…合作；與…聆手', 'to join forces or work together with someone', '[{"en":"We teamed up with a local distributor to enter the Asian market.","zh-TW":"我們與一家小地經销商合作，進入亞洲市場。"},{"en":"The two firms teamed up to bid on the contract together.","zh-TW":"這兩家公司聆手共同競標。"}]', 'phrasal verb'),
('come aboard', '加入團隊；加入公司', 'to join a team or organization', '[{"en":"We are thrilled to have you come aboard as our new CFO.","zh-TW":"我們很高興歡迎您加入擔任新的財務長。"},{"en":"When did the new sales director come aboard?","zh-TW":"新的銷售總監是何時加入的？"}]', 'phrasal verb'),
('stand in for', '代替；暫代其職', 'to substitute for someone temporarily', '[{"en":"Can you stand in for me at the client meeting on Friday?","zh-TW":"星期五的客戶會議，你能代替我嗎？"},{"en":"She stood in for the director while he was on leave.","zh-TW":"她在總監請假期間代行其職。"}]', 'phrasal verb'),
('double down on', '加倍投入；加大力度堅持某策略', 'to increase commitment to a course of action', '[{"en":"Despite criticism the company decided to double down on its expansion.","zh-TW":"對山面批評，公司卻決定加大力度推動擴張。"},{"en":"We should double down on digital marketing to capture more market share.","zh-TW":"我們應加大力度投入數位行銷以佔領更大市場份額。"}]', 'phrasal verb'),
('press ahead with', '繼續推進；堅持實行', 'to continue with something despite difficulties', '[{"en":"Management decided to press ahead with the restructuring plan.","zh-TW":"管理層決定繼續推進重組計畫。"},{"en":"We will press ahead with the launch despite the delay in approvals.","zh-TW":"面對審批延遲，我們將繼續推進發布。"}]', 'phrasal verb'),
('weigh in on', '就…發表意見；參與討論', 'to give one''s opinion or contribute to a discussion', '[{"en":"The CEO weighed in on the debate about remote work policy.","zh-TW":"執行長就遠端工作政策的討論發表了意見。"},{"en":"Please weigh in on the proposal before the deadline.","zh-TW":"請在截止日期前就提案發表您的意見。"}]', 'phrasal verb'),
('put in for', '申請；提出請求', 'to formally apply or request something', '[{"en":"She put in for a promotion after completing the project.","zh-TW":"她在完成專案後申請晉升。"},{"en":"He put in for two weeks of leave during the holiday period.","zh-TW":"他在假期期間申請了兩週休假。"}]', 'phrasal verb'),
('ease off', '放鬆；減輕壓力', 'to reduce pressure or slow down on something', '[{"en":"The workload eased off after the peak season ended.","zh-TW":"旺季結束後，工作量減輕了。"},{"en":"Management asked staff to ease off on overtime to prevent burnout.","zh-TW":"管理層要求員工減少加班，以防止過勞。"}]', 'phrasal verb'),
('grow into', '逐漸勝任；成長融入', 'to develop the skills needed for a role over time', '[{"en":"She is young but she will grow into the leadership role.","zh-TW":"她雖然年輕，但她將逐漸勝任領導職位。"},{"en":"New hires are expected to grow into their positions within six months.","zh-TW":"新員工預計在六個月內逐漸勝任各自的職位。"}]', 'phrasal verb'),
('check in with', '與…確認進度；向…報告', 'to contact someone to provide or receive an update', '[{"en":"Please check in with the team by end of day Friday.","zh-TW":"請在週五下班前與團隊確認進度。"},{"en":"The project manager checks in with each member every morning.","zh-TW":"專案經理每天早上與每位成員確認進度。"}]', 'phrasal verb'),
('table a proposal', '提出提案供討論；將提案納入議程', 'to formally present a proposal for discussion', '[{"en":"The committee tabled a proposal to revise the pricing structure.","zh-TW":"委員會提出了一項修訂定價結構的提案供討論。"},{"en":"We plan to table a proposal at the next board meeting.","zh-TW":"我們計劃在下次董事會會議上提出一項提案。"},{"note":"In American English, ''table'' can mean to postpone. In British English it means to bring forward for discussion"}]', 'business phrase'),
('come to an agreement', '達成協議；取得共識', 'to reach a mutual decision after negotiation', '[{"en":"After two days of talks the parties finally came to an agreement.","zh-TW":"經過兩天的會談，雙方最終達成了協議。"},{"en":"We hope to come to an agreement before the end of the quarter.","zh-TW":"我們希望在本季末之前達成協議。"}]', 'business phrase'),
('raise a concern', '提出顧慮；表達擔憂', 'to mention a worry or problem that needs attention', '[{"en":"Several board members raised concerns about the proposed merger.","zh-TW":"幾位董事會成員對擬議中的合併提出了顧慮。"},{"en":"Please raise any concerns before we finalize the contract.","zh-TW":"請在我們定稿合約前提出任何顧慮。"}]', 'business phrase'),
('set the agenda', '設定議程；決定討論事項', 'to determine what topics will be discussed in a meeting', '[{"en":"The chairperson sets the agenda for every quarterly review.","zh-TW":"主席為每次季度審查設定議程。"},{"en":"By setting the agenda early we ensure all key issues are covered.","zh-TW":"透過提早設定議程，我們確保所有關鍵議題都被涵蓋。"}]', 'business phrase'),
('adjourn the meeting', '休會；正式結束會議', 'to formally end or suspend a meeting', '[{"en":"The chairperson adjourned the meeting until the following Monday.","zh-TW":"主席將會議休會至下週一再繼續。"},{"en":"We adjourned the meeting early as the key decision-makers were absent.","zh-TW":"由於關鍵決策者缺席，我們提前休會。"}]', 'business phrase'),
('at an impasse', '陷入僵局；無法取得進展', 'in a deadlock where no progress can be made', '[{"en":"Negotiations are at an impasse over the intellectual property rights.","zh-TW":"談判在智慧財產權問題上陷入了僵局。"},{"en":"The two sides were at an impasse so mediation was requested.","zh-TW":"雙方陷入僵局，因此要求調解。"}]', 'expression'),
('split the difference', '各讓一半；折中妥協', 'to reach a compromise by each party conceding equally', '[{"en":"They could not agree on the price so they decided to split the difference.","zh-TW":"他們無法就價格達成協議，所以決定各讓一半。"},{"en":"Splitting the difference at fifty thousand satisfied both parties.","zh-TW":"以五萬元折中妥協令雙方都感到滿意。"}]', 'idiom'),
('put it to a vote', '付諸表決；進行投票決定', 'to decide something by having people vote', '[{"en":"Since we cannot reach consensus let us put it to a vote.","zh-TW":"既然我們無法達成共識，讓我們付諸表決。"},{"en":"The proposal was put to a vote and passed by a majority.","zh-TW":"提案付諸表決，並以多數通過。"}]', 'business phrase'),
('play devil''s advocate', '故意持反對立場；唱反調以引發討論', 'to argue the opposing side to stimulate discussion or test an idea', '[{"en":"Let me play devil''s advocate and ask why we should not proceed.","zh-TW":"讓我唱唱反調，問問為什麼我們不應該繼續。"},{"en":"Playing devil''s advocate is a useful way to stress-test a strategy.","zh-TW":"故意持反對立場是壓力測試策略的有效方式。"}]', 'idiom'),
('on the table', '在討論中；提供中', 'being offered or currently under consideration', '[{"en":"Several options are on the table and we will evaluate them next week.","zh-TW":"目前有幾個選項在討論中，我們下週將進行評估。"},{"en":"A significant pay rise is on the table if you take the new role.","zh-TW":"如果你接受新職位，可觀的薪資提升就在眼前。"}]', 'expression'),
('take a step back', '退一步思考；重新審視', 'to pause and reconsider the situation from a wider perspective', '[{"en":"Before deciding, let us take a step back and assess the risks.","zh-TW":"在做決定之前，讓我們退一步評估風險。"},{"en":"Taking a step back showed us that our approach was too narrow.","zh-TW":"退一步思考讓我們意識到自己的方法過於狹隘。"}]', 'expression'),
('reach a middle ground', '找到折中點；達成妥協方案', 'to find a compromise acceptable to both sides', '[{"en":"The two parties eventually reached a middle ground on delivery terms.","zh-TW":"雙方最終就交貨條款找到了折中點。"},{"en":"Our goal is to reach a middle ground that works for everyone involved.","zh-TW":"我們的目標是找到對所有相關人員都適用的折中方案。"}]', 'expression'),
('take the floor', '發言；取得發言權', 'to begin speaking formally in a meeting', '[{"en":"The VP of Sales took the floor to present the quarterly results.","zh-TW":"銷售副總裁發言報告了季度業績。"},{"en":"Would anyone like to take the floor before we move to the next item?","zh-TW":"在我們進入下一項目之前，有人想要發言嗎？"}]', 'business phrase'),
('open the floor', '開放發言；邀請大家提問', 'to invite others to speak or ask questions', '[{"en":"After the presentation she opened the floor to questions.","zh-TW":"簡報結束後，她開放發言讓大家提問。"},{"en":"Let us open the floor and hear what everyone thinks about this plan.","zh-TW":"讓我們開放發言，聽聽大家對這個計畫的看法。"}]', 'business phrase'),
('keep to the point', '切中要點；不偏離主題', 'to stay focused on the relevant topic without digressing', '[{"en":"Please keep to the point as we only have fifteen minutes.","zh-TW":"請切中要點，因為我們只有十五分鐘。"},{"en":"The facilitator reminded presenters to keep to the point during pitches.","zh-TW":"主持人提醒發表者在推介時切中要點。"}]', 'business phrase'),
('climb the ladder', '晉升；逐步升遷', 'to advance step by step to higher positions in a career', '[{"en":"He has been climbing the ladder steadily since joining the company.","zh-TW":"他自加入公司以來，一直穩步晉升。"},{"en":"Climbing the corporate ladder requires both talent and persistence.","zh-TW":"在企業晉升需要才能和毅力。"}]', 'idiom');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('get promoted', '獲得晉升；被升職', 'to be given a higher position or rank at work', '[{"en":"She worked hard for two years and finally got promoted to senior manager.","zh-TW":"她努力工作兩年，終於晉升為高級經理。"},{"en":"Getting promoted often requires demonstrating leadership potential.","zh-TW":"獲得晉升通常需要展示領導潛力。"}]', 'collocation'),
('take the initiative', '採取主動；主動行動', 'to act proactively without being told', '[{"en":"She took the initiative to redesign the onboarding process.","zh-TW":"她主動重新設計了入職流程。"},{"en":"Managers appreciate employees who take the initiative.","zh-TW":"管理者欣賞主動採取行動的員工。"}]', 'collocation'),
('a team player', '具有團隊精神的人；善於合作的人', 'someone who works well as part of a team', '[{"en":"We are looking for a team player who can collaborate across departments.","zh-TW":"我們正在尋找一位能跨部門合作、具有團隊精神的人。"},{"en":"Being a team player is just as important as individual performance.","zh-TW":"具有團隊精神與個人表現同樣重要。"}]', 'expression'),
('work-life balance', '工作與生活的平衡', 'a healthy balance between professional and personal life', '[{"en":"The company promotes work-life balance with flexible working hours.","zh-TW":"公司以彈性工時促進工作與生活的平衡。"},{"en":"Poor work-life balance can lead to burnout and high staff turnover.","zh-TW":"不良的工作與生活平衡可能導致過勞和高員工流動率。"}]', 'collocation'),
('move up the ranks', '在組織中升遷；職位提升', 'to advance to higher positions within an organization', '[{"en":"He moved up the ranks quickly thanks to his exceptional results.","zh-TW":"他因出色的業績而迅速在組織中升遷。"},{"en":"Moving up the ranks in a large corporation takes time and strategy.","zh-TW":"在大型企業中升遷需要時間和策略。"}]', 'expression'),
('in the running', '有競爭資格；角逐中', 'competing for a position or award', '[{"en":"She is in the running for the regional manager position.","zh-TW":"她正在角逐地區經理的職位。"},{"en":"Three candidates are still in the running after the first interview round.","zh-TW":"第一輪面試後，三位候選人仍在競爭中。"}]', 'expression'),
('keep one''s head above water', '勉強應付；維持正常運作', 'to manage to cope with a difficult workload or situation', '[{"en":"With three projects running simultaneously she struggled to keep her head above water.","zh-TW":"同時進行三個專案，她很難勉強應付。"},{"en":"We are keeping our heads above water but need more resources soon.","zh-TW":"我們目前勉強應付，但很快就需要更多資源。"}]', 'idiom'),
('dead-end job', '沒有前途的工作；死路一條的職位', 'a job with no possibility of advancement or improvement', '[{"en":"He left the dead-end job to pursue a career in technology.","zh-TW":"他辭去沒有前途的工作，轉而追求科技職涯。"},{"en":"Feeling stuck in a dead-end job can affect motivation and morale.","zh-TW":"覺得困在沒有前途的工作中會影響動力和士氣。"}]', 'collocation'),
('headhunted', '被獵頭；被挖角', 'approached by a recruiter to take a new job', '[{"en":"She was headhunted by a leading investment bank after her promotion.","zh-TW":"晉升後，她被一家頂尖投資銀行獵頭挖角。"},{"en":"Being headhunted is a sign that your skills are highly valued.","zh-TW":"被獵頭是你的技能備受重視的標誌。"}]', 'business phrase'),
('burn the midnight oil', '開夜車；工作到深夜', 'to work very late into the night', '[{"en":"The team burned the midnight oil to finish the proposal before the deadline.","zh-TW":"團隊開夜車在截止日期前完成了提案。"},{"en":"She burned the midnight oil for weeks preparing for the board presentation.","zh-TW":"她開了好幾週的夜車準備董事會簡報。"}]', 'idiom'),
('toe the line', '遵守規則；服從規定', 'to conform to expected standards or follow rules', '[{"en":"New employees are expected to toe the line during their probation period.","zh-TW":"新員工在試用期間需要遵守規則。"},{"en":"He was warned to toe the line or face disciplinary action.","zh-TW":"他被警告必須服從規定，否則將面臨紀律處分。"}]', 'idiom'),
('make a career move', '做出職涯轉換；採取職涯行動', 'to change jobs or make a strategic decision about one''s career', '[{"en":"She made a bold career move by switching from finance to tech.","zh-TW":"她大膽地從金融轉換到科技領域，做出了職涯轉換。"},{"en":"This is a smart career move given the growth of the industry.","zh-TW":"鑑於該行業的增長，這是一個明智的職涯行動。"}]', 'collocation'),
('job satisfaction', '工作滿意度；工作成就感', 'the sense of fulfillment and happiness from one''s work', '[{"en":"High job satisfaction leads to lower staff turnover.","zh-TW":"高工作滿意度會降低員工流動率。"},{"en":"She cited job satisfaction as the main reason for staying with the company.","zh-TW":"她將工作滿意度列為留在公司的主要原因。"}]', 'collocation'),
('on-the-job training', '在職培訓；邊做邊學', 'learning skills while performing the job rather than in a classroom', '[{"en":"New recruits receive on-the-job training during their first three months.","zh-TW":"新員工在前三個月接受在職培訓。"},{"en":"On-the-job training is the most practical way to develop industry skills.","zh-TW":"在職培訓是培養行業技能最實際的方式。"}]', 'collocation'),
('foot the bill', '付帳；承擔費用', 'to pay the cost of something, especially something expensive', '[{"en":"The company will foot the bill for all travel and accommodation expenses.","zh-TW":"公司將承擔所有差旅和住宿費用。"},{"en":"Who is going to foot the bill for the office renovation?","zh-TW":"誰來付辦公室裝修的帳？"}]', 'idiom'),
('tighten the belt', '縮緊開支；節省開銷', 'to spend less money and reduce expenses', '[{"en":"After the slowdown we had to tighten the belt across all departments.","zh-TW":"在業績放緩後，我們不得不在所有部門縮緊開支。"},{"en":"The company is tightening the belt by freezing all non-essential hiring.","zh-TW":"公司透過凍結所有非必要招聘來縮緊開支。"}]', 'idiom'),
('golden handshake', '優厚的離職補償；豐厚的解雇金', 'a generous financial package given to an executive upon leaving a company', '[{"en":"The departing CEO received a golden handshake worth five million dollars.","zh-TW":"離職的執行長獲得了價值五百萬美元的豐厚離職補償。"},{"en":"Golden handshakes are designed to secure a smooth leadership transition.","zh-TW":"優厚的離職補償旨在確保領導層的順利交接。"}]', 'collocation'),
('golden parachute', '黃金降落傘；高管離職保障金', 'a lucrative severance deal for executives if the company is acquired or they are dismissed', '[{"en":"His contract included a golden parachute clause worth ten million.","zh-TW":"他的合約包含一項價值一千萬的黃金降落傘條款。"},{"en":"Critics argue that golden parachutes reward failure rather than success.","zh-TW":"批評者認為黃金降落傘是在獎勵失敗而非成功。"}]', 'collocation'),
('money talks', '有錢能使鬼推磨；財力決定影響力', 'financial power has great influence in decisions and relationships', '[{"en":"In this industry money talks and the biggest spenders get the best deals.","zh-TW":"在這個行業，有錢能使鬼推磨，花費最多的人能拿到最好的交易。"},{"en":"He had the best idea but money talks, and the rival had deeper pockets.","zh-TW":"他有最好的創意，但財力決定影響力，競爭對手資金更雄厚。"}]', 'idiom'),
('on a shoestring budget', '以極少的預算；資金非常有限地', 'with very little money available', '[{"en":"They launched the product on a shoestring budget and still turned a profit.","zh-TW":"他們以極少的預算推出產品，卻仍然實現了盈利。"},{"en":"Managing a team on a shoestring budget requires creativity.","zh-TW":"以資金非常有限的預算管理團隊需要創意。"}]', 'expression'),
('burn through money', '快速消耗資金；大量花錢', 'to spend money very quickly', '[{"en":"The startup was burning through money faster than it was raising it.","zh-TW":"這家新創公司消耗資金的速度比募資還快。"},{"en":"Without cost controls we will burn through the budget in three months.","zh-TW":"沒有成本控制，我們將在三個月內燒完預算。"}]', 'expression'),
('revenue stream', '收入來源；資金流入管道', 'a source of income for a business', '[{"en":"The company is diversifying its revenue streams to reduce dependency on one product.","zh-TW":"公司正在多元化其收入來源，以減少對單一產品的依賴。"},{"en":"Licensing is a growing revenue stream for the tech firm.","zh-TW":"授權是該科技公司不斷增長的收入來源。"}]', 'collocation'),
('pay dividends', '帶來好處；產生回報', 'to produce benefits or profitable results over time', '[{"en":"Investing in staff training pays dividends in the long run.","zh-TW":"投資員工培訓從長遠來看會帶來好處。"},{"en":"The early sacrifices they made are now paying dividends.","zh-TW":"他們早期的犧牲現在正在產生回報。"},{"note":"Can refer to actual financial dividends or be used figuratively"}]', 'collocation'),
('cash-strapped', '資金拮据；資金短缺', 'having very little money available', '[{"en":"The cash-strapped startup had to delay its product launch.","zh-TW":"資金拮据的新創公司不得不推遲產品發布。"},{"en":"Many small businesses are cash-strapped during economic downturns.","zh-TW":"在經濟下行期間，許多小型企業資金短缺。"}]', 'collocation'),
('a windfall', '意外之財；意外橫財', 'an unexpected financial gain or profit', '[{"en":"The company received a windfall after selling its real estate assets.","zh-TW":"公司出售房地產資產後獲得了意外之財。"},{"en":"A windfall from the insurance claim helped them survive the crisis.","zh-TW":"保險理賠帶來的意外之財幫助他們度過了危機。"}]', 'business phrase'),
('on credit', '賒帳；先買後付', 'buying something now and paying for it later', '[{"en":"The company purchased the equipment on credit to preserve cash flow.","zh-TW":"公司賒帳購買設備以保護現金流。"},{"en":"Buying on credit can be useful but requires careful cash flow management.","zh-TW":"先買後付很有用，但需要謹慎管理現金流。"}]', 'expression'),
('overheads', '間接費用；日常營運開銷', 'the regular fixed costs of running a business such as rent and utilities', '[{"en":"Moving to a smaller office significantly reduced our overheads.","zh-TW":"搬到較小的辦公室大幅降低了我們的間接費用。"},{"en":"High overheads are eating into the company''s profit margins.","zh-TW":"高額的間接費用正在侵蝕公司的利潤率。"}]', 'collocation'),
('talk shop', '談公事；聊工作相關話題', 'to talk about work or business topics', '[{"en":"They met for coffee and ended up talking shop for two hours.","zh-TW":"他們喝咖啡時最後聊了兩小時的公事。"},{"en":"It is hard not to talk shop when you work with your best friend.","zh-TW":"當你和最好的朋友一起工作時，很難不聊工作話題。"}]', 'idiom'),
('put one''s cards on the table', '攤牌；坦誠說明立場', 'to be completely honest about one''s intentions or position', '[{"en":"Let me put my cards on the table and tell you exactly what we need.","zh-TW":"讓我攤牌，直接告訴你我們確切需要什麼。"},{"en":"She put her cards on the table and asked for a thirty percent raise.","zh-TW":"她攤牌，要求加薪三十個百分點。"}]', 'idiom'),
('a numbers game', '數字遊戲；靠量取勝的策略', 'a situation where success depends on large quantities rather than quality', '[{"en":"Cold calling is a numbers game — the more you call the more you close.","zh-TW":"電話推銷是數字遊戲——打越多電話，成交越多。"},{"en":"In recruiting, finding top talent is not just a numbers game.","zh-TW":"在招聘中，找到頂尖人才不僅僅是數字遊戲。"}]', 'expression'),
('a hard sell', '難以推銷；很難說服', 'something difficult to persuade people to accept or buy', '[{"en":"A price increase is always a hard sell to existing customers.","zh-TW":"漲價對現有客戶來說總是很難推銷的。"},{"en":"The new software was a hard sell without a proper demo.","zh-TW":"沒有適當的演示，新軟體很難說服人。"}]', 'expression'),
('bring up to speed', '向…更新情況；讓…了解最新動態', 'to give someone the latest information they need', '[{"en":"Can you bring the new team member up to speed on the project?","zh-TW":"你能讓新團隊成員了解專案的最新動態嗎？"},{"en":"She spent the morning bringing the client up to speed on the changes.","zh-TW":"她用了整個上午讓客戶了解最新的變化。"}]', 'phrasal verb'),
('narrow it down', '縮小範圍；精簡選擇', 'to reduce a number of options to a smaller, more manageable set', '[{"en":"We have five candidates — let us narrow it down to two.","zh-TW":"我們有五位候選人——讓我們把範圍縮小到兩位。"},{"en":"After the initial review we narrowed the vendor list down to three.","zh-TW":"初步審查後，我們將供應商名單縮小到三家。"}]', 'phrasal verb'),
('run past', '請人審閱；向某人諮詢', 'to tell someone about something to get their reaction or approval', '[{"en":"Let me run this pricing strategy past the finance team first.","zh-TW":"讓我先請財務團隊審閱這個定價策略。"},{"en":"Could you run the draft contract past legal before we sign?","zh-TW":"在我們簽署前，你能請法務審閱合約草案嗎？"}]', 'phrasal verb'),
('get down to brass tacks', '討論實質問題；切入正題', 'to start discussing the most important or practical details', '[{"en":"Let us get down to brass tacks and agree on the contract terms.","zh-TW":"讓我們切入正題，就合約條款達成協議。"},{"en":"After the introductions it is time to get down to brass tacks.","zh-TW":"介紹完畢後，是時候討論實質問題了。"}]', 'idiom'),
('take it or leave it', '愛要不要；不二價', 'a final offer with no room for further negotiation', '[{"en":"This is our final offer — take it or leave it.","zh-TW":"這是我們的最終出價——愛要不要。"},{"en":"He presented a take-it-or-leave-it proposal to close the negotiation.","zh-TW":"他提出了不二價的提案以結束談判。"}]', 'expression'),
('make concessions', '做出讓步；妥協', 'to give up something in order to reach an agreement', '[{"en":"Both parties had to make concessions to finalize the deal.","zh-TW":"雙方都必須做出讓步以完成交易。"},{"en":"He was unwilling to make any concessions on the delivery date.","zh-TW":"他不願意在交貨日期上做出任何讓步。"}]', 'collocation'),
('write off a debt', '核銷壞帳；沖銷債務', 'to officially accept that a debt will not be repaid and remove it from accounts', '[{"en":"The bank decided to write off the debt after the company went bankrupt.","zh-TW":"公司破產後，銀行決定核銷這筆壞帳。"},{"en":"Writing off a debt is a last resort after all collection efforts fail.","zh-TW":"核銷壞帳是在所有催收努力失敗後的最後手段。"}]', 'collocation'),
('fixed costs', '固定成本；不變費用', 'business expenses that remain constant regardless of output', '[{"en":"Rent and salaries are examples of fixed costs that do not change monthly.","zh-TW":"租金和薪資是每月不變的固定成本範例。"},{"en":"Reducing fixed costs is often the first step in a turnaround plan.","zh-TW":"降低固定成本通常是扭虧為盈計畫的第一步。"}]', 'collocation'),
('variable costs', '可變成本；隨產量變動的費用', 'business expenses that change depending on the level of production or sales', '[{"en":"As sales volume increases variable costs rise proportionally.","zh-TW":"隨著銷售量增加，可變成本按比例上升。"},{"en":"The company reduced variable costs by renegotiating supplier contracts.","zh-TW":"公司透過重新談判供應商合約降低了可變成本。"}]', 'collocation'),
('cash flow', '現金流量；資金流動', 'the movement of money in and out of a business', '[{"en":"Strong cash flow allows the company to invest in new opportunities.","zh-TW":"強勁的現金流量使公司能夠投資新機會。"},{"en":"Managing cash flow is essential for any small business to survive.","zh-TW":"管理現金流量對任何小型企業的生存都至關重要。"}]', 'collocation'),
('net profit', '淨利潤；純利', 'the profit remaining after all costs and taxes have been deducted', '[{"en":"The company reported a net profit of two million for the quarter.","zh-TW":"公司報告本季淨利潤為兩百萬。"},{"en":"Increasing net profit requires either growing revenue or cutting costs.","zh-TW":"增加淨利潤需要增加收入或削減成本。"}]', 'collocation'),
('operating expenses', '營運費用；日常業務支出', 'the day-to-day costs of running a business', '[{"en":"The new automation system significantly reduced our operating expenses.","zh-TW":"新的自動化系統大幅降低了我們的營運費用。"},{"en":"Operating expenses must be kept under control to maintain profitability.","zh-TW":"必須控制好營運費用以維持盈利能力。"}]', 'collocation'),
('asset allocation', '資產配置；資金分配', 'the distribution of investments across different asset categories', '[{"en":"A balanced asset allocation reduces overall portfolio risk.","zh-TW":"均衡的資產配置可降低整體投資組合風險。"},{"en":"The CFO reviewed the company''s asset allocation strategy quarterly.","zh-TW":"財務長每季審查公司的資產配置策略。"}]', 'collocation'),
('liquidity', '流動性；資金流通能力', 'the availability of liquid assets to meet short-term financial obligations', '[{"en":"The bank ran into trouble due to a lack of liquidity.","zh-TW":"銀行因流動性不足而陷入麻煩。"},{"en":"Maintaining adequate liquidity is critical during periods of uncertainty.","zh-TW":"在不確定時期維持足夠的流動性至關重要。"}]', 'business phrase'),
('burn rate', '資金消耗率；燒錢速度', 'the rate at which a company spends its capital before generating positive cash flow', '[{"en":"The startup''s burn rate means they have six months of runway left.","zh-TW":"這家新創公司的資金消耗率意味著他們只剩六個月的資金跑道。"},{"en":"Investors were concerned about the high burn rate with no revenue in sight.","zh-TW":"投資者對高燒錢速度卻看不到收入感到擔憂。"}]', 'collocation'),
('market cap', '市值；市場資本額', 'the total market value of a company''s outstanding shares', '[{"en":"The company''s market cap surpassed one billion dollars after the IPO.","zh-TW":"上市後公司市值突破十億美元。"},{"en":"Market cap is one indicator of a company''s size and investor confidence.","zh-TW":"市值是衡量公司規模和投資者信心的指標之一。"}]', 'collocation'),
('fiscal year', '財政年度；會計年度', 'a twelve-month period used for accounting and financial reporting', '[{"en":"The company''s fiscal year ends on March 31st rather than December 31st.","zh-TW":"公司的財政年度結束於三月三十一日而非十二月三十一日。"},{"en":"Revenue targets are set at the beginning of each fiscal year.","zh-TW":"收入目標在每個財政年度開始時設定。"}]', 'collocation'),
('venture capital', '創業投資；風險資本', 'funding provided to early-stage high-potential companies in exchange for equity', '[{"en":"The startup raised ten million in venture capital to fund its expansion.","zh-TW":"這家新創公司籌集了一千萬的創業投資來資助擴張。"},{"en":"Securing venture capital requires a compelling pitch and strong growth metrics.","zh-TW":"獲得創業投資需要引人注目的簡報和強勁的增長指標。"}]', 'collocation'),
('unique selling proposition', '獨特銷售主張；差異化優勢', 'the feature that makes a product or service different from competitors', '[{"en":"The brand''s unique selling proposition is its lifetime warranty.","zh-TW":"這個品牌的獨特銷售主張是其終身保固。"},{"en":"Defining your unique selling proposition is the first step in any marketing strategy.","zh-TW":"定義你的獨特銷售主張是任何行銷策略的第一步。"},{"note":"Often abbreviated as USP"}]', 'business phrase');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('customer retention', '客戶留存率；維繫客戶', 'the ability to keep existing customers over time', '[{"en":"Improving customer retention is more cost-effective than acquiring new customers.","zh-TW":"提升客戶留存率比獲取新客戶更具成本效益。"},{"en":"A loyalty programme is a popular strategy for boosting customer retention.","zh-TW":"忠誠度計畫是提升客戶留存率的常見策略。"}]', 'collocation'),
('turnaround time', '周轉時間；處理完成所需時間', 'the time taken to complete a task or process from start to finish', '[{"en":"Our average turnaround time for customer orders is forty-eight hours.","zh-TW":"我們客戶訂單的平均周轉時間為四十八小時。"},{"en":"Reducing turnaround time was the key goal of the process improvement project.","zh-TW":"縮短周轉時間是流程改善專案的關鍵目標。"}]', 'collocation'),
('trade surplus', '貿易順差；出口大於進口', 'when a country exports more than it imports', '[{"en":"The country maintained a trade surplus for the fifth consecutive year.","zh-TW":"該國連續第五年保持貿易順差。"},{"en":"A trade surplus can strengthen a country''s currency over time.","zh-TW":"貿易順差從長遠來看可能使一國貨幣升值。"}]', 'collocation'),
('trade deficit', '貿易逆差；進口大於出口', 'when a country imports more than it exports', '[{"en":"The widening trade deficit raised concerns among policymakers.","zh-TW":"不斷擴大的貿易逆差引起了政策制定者的擔憂。"},{"en":"Measures were introduced to reduce the trade deficit with key partners.","zh-TW":"採取了措施以減少與主要夥伴的貿易逆差。"}]', 'collocation'),
('barriers to entry', '進入壁壘；市場進入障礙', 'factors that make it difficult for new competitors to enter a market', '[{"en":"High start-up costs are a major barrier to entry in the pharmaceutical industry.","zh-TW":"高昂的啟動成本是製藥行業的主要進入壁壘。"},{"en":"Strong brand loyalty creates significant barriers to entry for new competitors.","zh-TW":"強烈的品牌忠誠度為新競爭者製造了重大的進入壁壘。"}]', 'collocation'),
('bulk order', '大量訂購；批量訂單', 'a large purchase of goods, usually at a discounted price', '[{"en":"Placing a bulk order reduces the unit cost significantly.","zh-TW":"大量訂購可以大幅降低單位成本。"},{"en":"The retail chain placed a bulk order ahead of the holiday season.","zh-TW":"連鎖零售商在假日季前下了批量訂單。"}]', 'collocation'),
('vendor management', '供應商管理；廠商關係管理', 'the process of overseeing and controlling relationships with suppliers', '[{"en":"Effective vendor management ensures consistent quality and timely delivery.","zh-TW":"有效的供應商管理確保一致的品質和及時交貨。"},{"en":"The procurement team improved vendor management by centralising all contracts.","zh-TW":"採購團隊透過集中管理所有合約改善了供應商管理。"}]', 'collocation'),
('change management', '變革管理；組織變革推動', 'the structured approach to transitioning individuals or organizations through change', '[{"en":"A solid change management plan minimises disruption during the merger.","zh-TW":"完善的變革管理計畫可在合併期間將干擾降至最低。"},{"en":"Change management requires clear communication and strong leadership.","zh-TW":"變革管理需要清晰的溝通和強有力的領導。"}]', 'collocation'),
('organizational culture', '組織文化；企業文化', 'the shared values, beliefs, and practices within an organization', '[{"en":"A positive organizational culture attracts and retains top talent.","zh-TW":"積極的組織文化能吸引並留住頂尖人才。"},{"en":"The new CEO prioritized transforming the organizational culture.","zh-TW":"新執行長優先致力於轉變組織文化。"}]', 'collocation'),
('benchmarking', '標竿管理；比較基準', 'the practice of comparing business processes and metrics against industry best performers', '[{"en":"Benchmarking against competitors revealed gaps in our customer service.","zh-TW":"與競爭對手的標竿比較揭示了我們客戶服務的差距。"},{"en":"The company uses benchmarking to set realistic performance targets.","zh-TW":"公司使用標竿管理來設定切實可行的績效目標。"}]', 'business phrase'),
('best practice', '最佳實踐；最佳做法', 'the most effective method or approach accepted as superior in an industry', '[{"en":"Sharing best practices across departments improves overall performance.","zh-TW":"在各部門間分享最佳實踐可提升整體績效。"},{"en":"The manual documents best practices for handling client complaints.","zh-TW":"該手冊記錄了處理客戶投訴的最佳做法。"}]', 'collocation'),
('key deliverable', '關鍵交付成果；重要輸出項目', 'a specific, tangible output that must be produced as part of a project', '[{"en":"The key deliverables for this phase include a prototype and a test report.","zh-TW":"這個階段的關鍵交付成果包括原型和測試報告。"},{"en":"All team members must be clear on the key deliverables before work begins.","zh-TW":"所有團隊成員在開始工作之前必須清楚關鍵交付成果。"}]', 'collocation'),
('break ranks', '打破常規；不服從集體決定', 'to act against the decisions or rules of one''s group', '[{"en":"One board member broke ranks and voted against the proposal.","zh-TW":"一位董事會成員打破常規，投票反對該提案。"},{"en":"Breaking ranks on this issue could damage team cohesion.","zh-TW":"在這個問題上打破常規可能會損害團隊凝聚力。"}]', 'idiom'),
('sleeping partner', '隱名合夥人；不參與日常管理的投資人', 'a business partner who provides capital but takes no active role in management', '[{"en":"He acts as a sleeping partner and does not attend board meetings.","zh-TW":"他作為隱名合夥人，不出席董事會會議。"},{"en":"The firm brought in a sleeping partner to fund the new division.","zh-TW":"公司引入了隱名合夥人為新部門提供資金。"}]', 'business phrase'),
('get the message across', '傳達清楚；讓人明白意思', 'to communicate an idea successfully so others understand it', '[{"en":"Use visuals to get the message across more effectively in presentations.","zh-TW":"在簡報中使用視覺效果更有效地傳達意思。"},{"en":"She struggled to get the message across to the non-technical audience.","zh-TW":"她難以向非技術背景的聽眾傳達清楚她的意思。"}]', 'expression'),
('take on board', '接受；認真考慮（意見或建議）', 'to accept and consider feedback or advice seriously', '[{"en":"Management took the team''s concerns on board and revised the plan.","zh-TW":"管理層認真考慮了團隊的顧慮並修訂了計畫。"},{"en":"She took all the client''s feedback on board before the final presentation.","zh-TW":"她在最終簡報前認真考慮了所有客戶的反饋。"}]', 'phrasal verb'),
('non-disclosure', '保密；不披露協議', 'an agreement to keep certain information confidential', '[{"en":"Both parties signed a non-disclosure agreement before sharing financials.","zh-TW":"雙方在分享財務資料前簽署了保密協議。"},{"en":"The non-disclosure clause prevents either party from revealing trade secrets.","zh-TW":"保密條款防止任何一方洩露商業機密。"},{"note":"Commonly used as in ''non-disclosure agreement'' or NDA"}]', 'collocation'),
('think big', '有遠大抱負；敢於宏觀思考', 'to have ambitious and broad goals rather than limiting oneself', '[{"en":"The founder encouraged the team to think big and set bold targets.","zh-TW":"創辦人鼓勵團隊有遠大抱負，設定大膽的目標。"},{"en":"Thinking big is important but must be backed by a solid execution plan.","zh-TW":"有遠大抱負很重要，但必須有扎實的執行計畫支撐。"}]', 'expression'),
('sweeten the deal', '讓條件更具吸引力；增加優惠', 'to make an offer more attractive by adding extra benefits', '[{"en":"They sweetened the deal by offering free shipping and extended warranties.","zh-TW":"他們透過提供免費運送和延長保固來讓條件更具吸引力。"},{"en":"To close the sale the manager sweetened the deal with a ten percent discount.","zh-TW":"為了完成銷售，經理增加了十個百分點的折扣作為優惠。"}]', 'idiom'),
('a blank check', '無限授權；充分授權', 'complete freedom to act or spend as much as needed', '[{"en":"The CEO was given a blank check to restructure the failing division.","zh-TW":"執行長獲得無限授權來重組虧損部門。"},{"en":"Giving a vendor a blank check without oversight can lead to budget overruns.","zh-TW":"在沒有監督的情況下給供應商無限授權可能導致預算超支。"}]', 'idiom'),
('top-down approach', '由上而下的方式；高層主導', 'a method where decisions and instructions come from senior management', '[{"en":"The new strategy was communicated through a top-down approach.","zh-TW":"新策略透過由上而下的方式傳達。"},{"en":"A top-down approach ensures consistency but may reduce employee buy-in.","zh-TW":"由上而下的方式確保一致性，但可能降低員工的認同感。"}]', 'business phrase'),
('lead time', '前置時間；備貨所需時間', 'the time between placing an order and receiving the goods or completing a task', '[{"en":"The lead time for this supplier is typically six weeks.","zh-TW":"這家供應商的前置時間通常為六週。"},{"en":"Reducing lead time gives the company a competitive advantage.","zh-TW":"縮短前置時間使公司具有競爭優勢。"}]', 'collocation'),
('value-added', '增值的；附加價值的', 'providing extra benefit or enhancement beyond the basic product or service', '[{"en":"The consultants offered value-added services such as training and support.","zh-TW":"顧問提供了包括培訓和支援在內的增值服務。"},{"en":"Value-added features can justify a higher price point.","zh-TW":"增值功能可以為更高的定價提供依據。"}]', 'collocation'),
('red ocean', '紅海市場；競爭激烈的既有市場', 'a highly competitive market where companies fight for existing demand', '[{"en":"The smartphone market has become a red ocean with shrinking margins.","zh-TW":"智慧型手機市場已成為利潤空間收窄的紅海市場。"},{"en":"Instead of competing in a red ocean we are creating a new market category.","zh-TW":"我們不是在紅海市場競爭，而是正在創造一個新的市場類別。"},{"note":"Contrasts with ''blue ocean'' (uncontested market space)"}]', 'business phrase'),
('blue ocean', '藍海市場；未開發的新市場空間', 'an untapped or uncontested market space with little to no competition', '[{"en":"The company found its blue ocean by targeting underserved rural customers.","zh-TW":"公司透過鎖定服務不足的農村客戶找到了自己的藍海市場。"},{"en":"Blue ocean strategy focuses on creating demand rather than competing for it.","zh-TW":"藍海策略專注於創造需求而非爭奪需求。"},{"note":"Contrasts with ''red ocean'' (highly competitive existing market)"}]', 'business phrase'),
('scope of work', '工作範圍；專案範疇', 'the defined tasks, deliverables, and boundaries of a project', '[{"en":"The scope of work must be agreed before signing the service contract.","zh-TW":"在簽署服務合約前必須就工作範圍達成共識。"},{"en":"Any changes to the scope of work will require a revised budget estimate.","zh-TW":"工作範圍的任何變更都需要修訂預算估算。"}]', 'collocation'),
('quid pro quo', '交換條件；以物易物', 'a favour or advantage given in return for something of equal value', '[{"en":"The partnership was built on a quid pro quo of shared resources and contacts.","zh-TW":"這次合作建立在共享資源和人脈的交換條件基礎上。"},{"en":"In diplomacy and business, quid pro quo arrangements are common.","zh-TW":"在外交和商業中，交換條件安排很常見。"}]', 'business phrase'),
('market positioning', '市場定位；品牌定位策略', 'the way a company differentiates its product in the minds of consumers', '[{"en":"The rebranding effort was designed to improve the company''s market positioning.","zh-TW":"重新品牌化工作旨在改善公司的市場定位。"},{"en":"Strong market positioning allows a company to command premium prices.","zh-TW":"強有力的市場定位使公司能夠維持溢價。"}]', 'collocation'),
('pricing strategy', '定價策略；價格制定方式', 'the method used to set the price of a product or service', '[{"en":"The company adopted a penetration pricing strategy to gain market share quickly.","zh-TW":"公司採用滲透定價策略迅速獲取市場份額。"},{"en":"Choosing the right pricing strategy is critical for sustainable profitability.","zh-TW":"選擇正確的定價策略對可持續盈利至關重要。"}]', 'collocation'),
('brand awareness', '品牌知名度；品牌認知度', 'the extent to which consumers are familiar with a brand and its products', '[{"en":"Social media campaigns significantly increased brand awareness among young consumers.","zh-TW":"社交媒體活動顯著提高了年輕消費者的品牌知名度。"},{"en":"Building brand awareness takes time and consistent marketing investment.","zh-TW":"建立品牌知名度需要時間和持續的行銷投入。"}]', 'collocation'),
('demand forecast', '需求預測；市場需求預估', 'an estimate of future customer demand for a product or service', '[{"en":"Accurate demand forecasting reduces the risk of overstock or shortages.","zh-TW":"準確的需求預測可降低庫存過多或短缺的風險。"},{"en":"The demand forecast for Q4 suggests a thirty percent increase in orders.","zh-TW":"第四季的需求預測顯示訂單增加三十個百分點。"}]', 'collocation');
INSERT INTO grammar_topics (id, title, category, level, explanation_md) VALUES
(1, 'Present Simple vs Present Continuous', 'tense', 2, '現在簡單式用於習慣或事實（She works every day），現在進行式用於當下正在發生的動作（She is working now）。靜態動詞如 know、believe 不用進行式。商業英語中，簡單式描述職責，進行式描述當前專案。'),
(2, 'Past Simple vs Past Continuous', 'tense', 2, '過去簡單式描述已完成的過去動作，過去進行式描述過去某時刻正在進行的動作。兩者常搭配：進行式為背景，簡單式為插入動作。'),
(3, 'Present Perfect', 'tense', 3, '現在完成式（have/has + 過去分詞）連結過去動作與現在結果，常與 just、already、yet、ever、never、since、for 連用，不與 yesterday、last year 等明確過去時間連用。'),
(4, 'Present Perfect vs Past Simple', 'tense', 3, '現在完成式強調對現在的影響；過去簡單式描述已結束的特定事件。ago/yesterday/last year → 過去式；already/yet/just/since/for → 完成式。'),
(5, 'Past Perfect', 'tense', 3, '過去完成式（had + 過去分詞）描述過去某時間點之前已完成的動作，建立兩個過去事件的先後順序，常與 before、by the time、when、already 等連用。'),
(6, 'Future: will vs going to', 'tense', 2, 'will 用於臨時決定、承諾或預測；be going to 用於已計劃的意圖或根據證據的預測。兩者均可表未來，but 語用不同。'),
(7, 'Future Perfect and Future Continuous', 'tense', 4, '未來完成式（will have + p.p.）表示到未來某點前將完成的動作；未來進行式（will be + V-ing）表示未來某時刻正在進行的動作。兩者常用於商業時程規劃。'),
(8, 'Mixed Tenses', 'tense', 4, '混合時態練習要求根據語境選擇正確時態，是商業英語的重要能力。正確選擇時態能清楚傳達事件的時間順序和因果關係。'),
(9, 'Definite Article: the', 'article', 2, '定冠詞 the 用於雙方均知的特定事物、再次提及、獨一無二的事物及最高級前。商業英語中常見於職稱（the CEO）、特定文件（the report）、最高級（the best）。'),
(10, 'Indefinite Articles: a / an', 'article', 1, '不定冠詞 a 用在輔音音素前，an 用在母音音素前。注意判斷依據是發音不是拼字（如 an hour、an MBA）。用於首次提及或泛指某類別。'),
(11, 'Zero Article', 'article', 3, '零冠詞（不加冠詞）用於複數可數名詞泛稱、不可數名詞泛稱、專有名詞、及 go to work/by email 等固定搭配。避免在泛稱前加 the。'),
(12, 'Prepositions of Time: at/in/on', 'preposition', 2, 'at 用於精確時間（at 3 p.m.）；in 用於較長時段（in March、in 2024）；on 用於特定日期和星期（on Monday、on January 5th）。商業場合中正確使用避免誤解。'),
(13, 'Prepositions of Place: at/in/on', 'preposition', 2, 'at 表精確地點或功能性場所（at the reception）；in 表有邊界空間或地區（in the office）；on 表面或樓層（on the desk、on the third floor）。'),
(14, 'Prepositions of Movement', 'preposition', 2, '移動介系詞描述從一地到另一地的動作：to（去到）、into（進入）、out of（出去）、through（穿過）、across（橫越）、along（沿著）、past（經過）。'),
(15, 'Dependent Prepositions (adjective + prep)', 'preposition', 3, '形容詞與特定介系詞的固定搭配，如 responsible for、interested in、satisfied with、familiar with。必須記憶，不可任意替換。'),
(16, 'Dependent Prepositions (verb + prep)', 'preposition', 3, '動詞與特定介系詞的固定搭配，如 apply for、deal with、rely on、invest in。錯誤使用介系詞會造成誤解，需熟記常見搭配。'),
(17, 'Zero and First Conditional', 'conditional', 2, '零條件句（if + 現在式，現在式）表普遍事實；第一條件句（if + 現在式，will）表真實可能的未來情況。商業英語常用第一條件句提案或預測。'),
(18, 'Second Conditional', 'conditional', 3, '第二條件句（if + 過去式，would）表示假設或不太可能的情況。注意 if 子句中 be 動詞正式英語用 were，常用於假設討論和商業頭腦風暴。'),
(19, 'Third Conditional', 'conditional', 4, '第三條件句（if + had + p.p.，would have + p.p.）描述過去假設，用於反思決策。商業案例分析和後見之明討論中常見。'),
(20, 'Mixed Conditionals', 'conditional', 5, '混合條件句結合不同時態：最常見是 if + 過去完成式（過去假設），would + 原形（現在結果），如 If I had taken that job, I would be in London now。'),
(21, 'Modal: can / could', 'modal', 2, 'can 表現在的能力、許可或可能性；could 表過去能力、假設可能性或禮貌請求。商業英語中 could 比 can 更正式有禮貌。'),
(22, 'Modal: must / have to', 'modal', 2, 'must 表主觀強烈義務或邏輯推論；have to 表外在客觀規定。must not 表禁止；do not have to 表不必要（不是禁止）。'),
(23, 'Modal: should / ought to', 'modal', 2, 'should 和 ought to 表建議或期望，should 更口語常用。商業英語中 should 常見於建議、指南、政策手冊中。'),
(24, 'Modal: may / might', 'modal', 3, 'may 和 might 都表可能性，might 確定性略低。may 也可表正式許可。商業報告中用於謹慎預測，避免過於武斷。'),
(25, 'Modal: would', 'modal', 3, 'would 多用法：過去習慣、禮貌請求（Would you...）、假設（I would accept）、提供建議（I would recommend）。商業溝通中是最禮貌的情態動詞。'),
(26, 'Modal Perfect: should have / could have / would have', 'modal', 4, '情態完成式談論過去不同的可能：should have（應該做但沒做，遺憾/批評），could have（本可以，可能性），would have（假設結果）。'),
(27, 'Passive Voice: Simple Tenses', 'passive', 3, '被動語態（am/is/are/was/were + p.p.）強調動作接受者，廣泛用於商業正式文件。當行為者不重要或不明確時特別適用。'),
(28, 'Passive Voice: Perfect Tenses', 'passive', 4, '完成被動式：現在完成被動（have/has been + p.p.）和過去完成被動（had been + p.p.）。商業報告中用於說明已完成的程序，語氣正式客觀。'),
(29, 'Passive Voice: Modal Verbs', 'passive', 4, '情態被動（modal + be + p.p.）廣泛用於商業政策和通知：must be submitted、should be reviewed、will be sent、can be accessed。'),
(30, 'Causative Have/Get', 'passive', 4, '使役結構：have/get something done（安排別人做）；have someone do（主動命令）；get someone to do（說服/促使）。常用於委託、外包描述。'),
(31, 'Reported Speech: Statements', 'reported speech', 3, '間接引語將直接引語轉為第三人稱，動詞時態後移，代名詞和時間副詞也需調整。商業會議記錄和轉述客戶意見時常用。'),
(32, 'Reported Speech: Questions', 'reported speech', 3, '間接問句語序是陳述句序，no 不用問號。yes/no 問句用 if/whether 引導。如：She asked what the deadline was；He asked if the report was ready。'),
(33, 'Reported Speech: Commands', 'reported speech', 3, '間接命令句：tell/ask/order/advise + 受詞 + to do（肯定）；tell + 受詞 + not to do（否定）。'),
(34, 'Backshift in Reported Speech', 'reported speech', 4, '間接引語時態後移規則：現在→過去，過去→過去完成，will→would，can→could，may→might。時間副詞：now→then，today→that day，tomorrow→the following day，here→there。'),
(35, 'Defining Relative Clauses', 'relative clause', 3, '限定性關係子句提供識別被修飾名詞所必需的資訊，不用逗號，可用 who（人）、which（物）、that（人或物）、whose（所有格）。'),
(36, 'Non-defining Relative Clauses', 'relative clause', 4, '非限定性關係子句提供額外（非必要）資訊，用逗號隔開，不可用 that，只用 who/which/whose/where/when。'),
(37, 'Relative Pronouns: who/which/that/whose', 'relative clause', 3, 'who 指人（主格/受格），which 指物（限定/非限定），that 指人或物（只限限定子句），whose 表所有格（人或物）。'),
(38, 'Gerund vs Infinitive after Verbs', 'gerund/infinitive', 3, '某些動詞後接動名詞（enjoy/finish/suggest/consider/avoid），某些後接不定詞（want/decide/agree/plan/refuse），有些兩者皆可但意思可能不同（stop/remember/try）。'),
(39, 'Gerund as Subject', 'gerund/infinitive', 2, '動名詞可作句子主語，如 Managing a team requires strong communication skills。這種結構在商業政策說明、工作描述中非常常見。'),
(40, 'Infinitive of Purpose', 'gerund/infinitive', 2, '不定詞表目的（to do），更正式用 in order to 或 so as to。商業英語中清楚說明行動目的，常見於策略計劃和提案。'),
(41, 'Verb + Object + Infinitive', 'gerund/infinitive', 3, '某些動詞後接受詞再接不定詞：want/ask/advise/require/expect/allow/encourage + 受詞 + to do。商業指示和委託中大量使用。'),
(42, 'Comparative Adjectives', 'comparison', 2, '比較級：單音節 + -er（faster）；多音節 + more（more efficient）；不規則：good→better，bad→worse，far→farther/further。'),
(43, 'Superlative Adjectives', 'comparison', 2, '最高級：單音節 + the -est（the fastest）；多音節 + the most（the most innovative）；不規則：good→the best，bad→the worst。'),
(44, 'Comparing with as...as', 'comparison', 2, 'as + 形容詞/副詞 + as 表相等；not as...as 表不如；the same...as 表相同；as much/many...as 表數量相等。'),
(45, 'Double Comparatives', 'comparison', 4, '雙重比較結構 the + 比較級 + the + 比較級，表示正比或反比關係。常見於商業策略討論，如 The more we invest, the higher the returns。'),
(46, 'Adverbial Clauses of Time', 'clause', 3, '時間副詞子句由 when、while、as soon as、before、after、until、by the time 等引導，表示動作發生的時間關係。'),
(47, 'Adverbial Clauses of Reason', 'clause', 3, '原因副詞子句由 because、since、as、now that 等引導，解釋動作的原因。商業英語中常用於說明決策理由。'),
(48, 'Adverbial Clauses of Contrast', 'clause', 3, '對比副詞子句由 although、even though、while、whereas 等引導，承認一個事實同時提出相反情況。商業英語中用於客觀分析。'),
(49, 'Adverbial Clauses of Result', 'clause', 3, '結果副詞子句由 so...that 或 such...that 引導，表示原因導致的結果。如 The presentation was so compelling that the client signed immediately。'),
(50, 'Noun Clauses', 'clause', 4, '名詞子句充當名詞功能（主語、受語或補語），常由 that、whether、what、how、why、who 等引導。商業英語中常用於表達觀點和轉述資訊。');